pub trait Default {
    fn default() -> Self
}

impl Default for () {
    fn default() -> Self {
        ()
    }
}

impl<const N: usize> Default for String<N> {
    fn default() -> Self {
        ""
    }
}

impl Default for Bytes {
    fn default() -> Self {
        Bytes::empty()
    }
}

impl Default for DynString {
    fn default() -> Self {
        DynString::empty()
    }
}

impl<T0> Default for (T0,)
    where T0: Default
{
    fn default() -> Self {
        (T0::default(),)
    }
}

