impl<S: IntWord, T: IntWord> IntDowncast<T> for S {
    const fn downcast(self) -> Option<T> {
        let word = IntWord::to_word(self)
        if T::IS_SIGNED {
            let t_min_word = sign_extend(word: T::SIGN_BIT, mask: T::MASK, sign_bit: T::SIGN_BIT)
            let t_max_word = T::SIGN_BIT - 1
            let t_min: i256 = __bitcast(t_min_word)
            let t_max: i256 = __bitcast(t_max_word)

            if !S::IS_SIGNED && (word & I256_SIGN_BIT != 0) {
                Option::None
            } else {
                let x: i256 = __bitcast(word)
                if x < t_min {
                    Option::None
                } else if x > t_max {
                    Option::None
                } else {
                    Option::Some(T::from_word(word))
                }
            }
        } else {
            if S::IS_SIGNED && (word & I256_SIGN_BIT != 0) {
                Option::None
            } else if word > T::MASK {
                Option::None
            } else {
                Option::Some(T::from_word(word))
            }
        }
    }

    const fn downcast_truncate(self) -> T {
        let word = IntWord::to_word(self)
        if T::IS_SIGNED {
            T::from_word(sign_extend(word: word, mask: T::MASK, sign_bit: T::SIGN_BIT))
        } else {
            T::from_word(word & T::MASK)
        }
    }

    const fn downcast_saturate(self) -> T {
        let word = IntWord::to_word(self)
        if !T::IS_SIGNED {
            var unsigned_word = word
            if S::IS_SIGNED && (word & I256_SIGN_BIT != 0) {
                unsigned_word = 0
            }

            if unsigned_word > T::MASK {
                T::from_word(T::MASK)
            } else {
                T::from_word(unsigned_word)
            }
        } else {
            let t_min_word = sign_extend(word: T::SIGN_BIT, mask: T::MASK, sign_bit: T::SIGN_BIT)
            let t_max_word = T::SIGN_BIT - 1
            let t_min: i256 = __bitcast(t_min_word)
            let t_max: i256 = __bitcast(t_max_word)

            if S::IS_SIGNED {
                let x: i256 = __bitcast(word)
                if x < t_min {
                    T::from_word(t_min_word)
                } else if x > t_max {
                    T::from_word(t_max_word)
                } else {
                    T::from_word(word)
                }
            } else {
                if word & I256_SIGN_BIT != 0 {
                    T::from_word(t_max_word)
                } else {
                    let x: i256 = __bitcast(word)
                    if x > t_max {
                        T::from_word(t_max_word)
                    } else {
                        T::from_word(word)
                    }
                }
            }
        }
    }

    const fn downcast_unchecked(self) -> T {
        let word = IntWord::to_word(self)
        T::from_word(word)
    }
}

/// Performs two's-complement sign extension within the provided mask/sign bit.
pub const fn sign_extend(word: u256, _ mask: u256, _ sign_bit: u256) -> u256 {
    let value = word & mask
    if value & sign_bit != 0 {
        value | (U256_MASK ^ mask)
    } else {
        value
    }
}

/// Returns floor(sqrt(x)), i.e. the largest `z` such that `z * z <= x`.
#[arithmetic(unchecked)]
pub fn isqrt(_ x: u256) -> u256 {
    if x == 0 {
        return 0
    }

    // Seed with `1 << (log2(x) / 2)`, a power of two within a factor of two
    // of the true root, so a fixed number of Newton iterations suffices.
    var y = x
    var z: u256 = 1
    if y >= 1 << 128 {
        y >>= 128
        z <<= 64
    }
    if y >= 1 << 64 {
        y >>= 64
        z <<= 32
    }
    if y >= 1 << 32 {
        y >>= 32
        z <<= 16
    }
    if y >= 1 << 16 {
        y >>= 16
        z <<= 8
    }
    if y >= 1 << 8 {
        y >>= 8
        z <<= 4
    }
    if y >= 1 << 4 {
        y >>= 4
        z <<= 2
    }
    if y >= 1 << 2 {
        z <<= 1
    }

    // Newton's method doubles the number of correct bits per step, so seven
    // iterations refine the seed past the 128 bits a root can occupy.
    z = (z + x / z) >> 1
    z = (z + x / z) >> 1
    z = (z + x / z) >> 1
    z = (z + x / z) >> 1
    z = (z + x / z) >> 1
    z = (z + x / z) >> 1
    z = (z + x / z) >> 1

    // Newton converges from above and can settle on `floor + 1`; subtract
    // one exactly when `z` overshoots (`z > x / z`) to round down to the floor.
    let q = x / z
    z - ((z > q) as u256)
}

extern {
    /// Returns the number of leading zero bits in `x`, or 256 if `x == 0`.
    ///
    /// Lowers to the EVM `CLZ` instruction (EIP-7939).
    pub const fn leading_zeros(_ x: u256) -> u256
}

/// Returns the number of trailing zero bits in `x`, or 256 if `x == 0`.
#[arithmetic(unchecked)]
pub const fn trailing_zeros(_ x: u256) -> u256 {
    if x == 0 {
        return 256
    }
    // `x & -x` isolates the lowest set bit.
    255 - leading_zeros(x & (0 - x))
}

/// Returns the greatest common divisor of `a` and `b`.
///
/// `gcd(a, 0) == gcd(0, a) == a`, so `gcd(0, 0) == 0`. Never fails.
///
/// Uses Euclid's algorithm with `%`, so gas depends on the inputs: one loop
/// iteration per remainder step, at most 368 for `u256` operands (reached
/// by consecutive Fibonacci numbers) and far fewer for typical values.
#[arithmetic(unchecked)]
pub const fn gcd(_ a: u256, _ b: u256) -> u256 {
    var x = a
    var y = b
    while y != 0 {
        let r = x % y
        x = y
        y = r
    }
    x
}

extern {
    /// Returns `(a + b) % m` with a 257-bit intermediate sum, or 0 if `m == 0`.
    pub const fn addmod(_ a: u256, _ b: u256, _ m: u256) -> u256
    /// Returns `(a * b) % m` with a 512-bit intermediate product, or 0 if `m == 0`.
    pub const fn mulmod(_ a: u256, _ b: u256, _ m: u256) -> u256
}

/// Returns the full 512-bit product `a * b` as `(high, low)` words.
#[arithmetic(unchecked)]
pub const fn full_mul(_ a: u256, _ b: u256) -> (u256, u256) {
    let low = a * b
    let mm = mulmod(a, b, u256::max())
    (mm - low - ((mm < low) as u256), low)
}

/// Returns `floor(a * b / d)` computed with a 512-bit intermediate product,
/// or `None` if `d == 0` or the result does not fit in a `u256`.
///
/// Algorithm by Remco Bloemen (https://xn--2-umb.com/21/muldiv), as used in
/// Uniswap's MIT-licensed FullMath.
#[arithmetic(unchecked)]
pub const fn checked_mul_div(_ a: u256, _ b: u256, _ d: u256) -> Option<u256> {
    let (var high, var low) = full_mul(a, b)
    // Also rejects `d == 0`.
    if d <= high {
        return None
    }
    if high == 0 {
        return Some(low / d)
    }

    // Make the division exact by subtracting the remainder from [high low].
    let remainder = mulmod(a, b, d)
    high = high - ((remainder > low) as u256)
    low = low - remainder

    // Factor powers of two out of `d` and shift them out of [high low].
    let twos = (0 - d) & d
    let odd = d / twos
    low = low / twos
    let shift = (0 - twos) / twos + 1
    low = low | (high * shift)

    // `odd` is invertible modulo 2^256; Newton-Raphson doubles the correct
    // bits per step, starting from 4 correct bits.
    var inverse = (3 * odd) ^ 2
    inverse = inverse * (2 - odd * inverse)
    inverse = inverse * (2 - odd * inverse)
    inverse = inverse * (2 - odd * inverse)
    inverse = inverse * (2 - odd * inverse)
    inverse = inverse * (2 - odd * inverse)
    inverse = inverse * (2 - odd * inverse)
    Some(low * inverse)
}

/// Returns `ceil(a * b / d)` computed with a 512-bit intermediate product,
/// or `None` if `d == 0` or the result does not fit in a `u256`.
pub const fn checked_mul_div_ceil(_ a: u256, _ b: u256, _ d: u256) -> Option<u256> {
    match checked_mul_div(a, b, d) {
        Some(result) => {
            if mulmod(a, b, d) == 0 {
                Some(result)
            } else if result == u256::max() {
                None
            } else {
                Some(result + 1)
            }
        }
        None => None,
    }
}

/// Returns `floor(a * b / d)` computed with a 512-bit intermediate product.
///
/// Fails like checked arithmetic: division by zero if `d == 0`, overflow if
/// the result does not fit in a `u256`.
pub const fn mul_div(_ a: u256, _ b: u256, _ d: u256) -> u256 {
    match checked_mul_div(a, b, d) {
        Some(result) => result,
        None => mul_div_failure(d),
    }
}

/// Returns `ceil(a * b / d)` computed with a 512-bit intermediate product.
///
/// Fails like checked arithmetic: division by zero if `d == 0`, overflow if
/// the result does not fit in a `u256`.
pub const fn mul_div_ceil(_ a: u256, _ b: u256, _ d: u256) -> u256 {
    match checked_mul_div_ceil(a, b, d) {
        Some(result) => result,
        None => mul_div_failure(d),
    }
}

// Raises the checked-arithmetic failure of a rejected `mul_div`.
const fn mul_div_failure(_ d: u256) -> u256 {
    let _ = 1 / d
    // Only reached for `d != 0`, so this addition overflows.
    d + u256::max()
}

const fn pow_checked<T>(_ base: own T, _ exp: own T) -> T
    where T: IntWord, T: Mul<Output = T>
{
    __checked_pow(base, exp)
}

