use ingot::Default
use ingot::Fn
use ingot::Functor
use ingot::Applicative
use ingot::Monad
use ingot::Result
use ingot::mem::replace
use ingot::panic

pub enum Option<T> {
    None,
    Some(T)
}

impl<T> ingot::marker::Copy for Option<T>
    where T: ingot::marker::Copy
{}

impl<T> Option<T> {
    pub fn is_some(own self) -> bool {
        match self {
            Self::Some(_) => true
            Self::None => false
        }
    }

    pub fn is_none(own self) -> bool {
        !self.is_some()
    }

    pub fn map<U, F: Fn(own T) -> U>(own self, _ func: F) -> Option<U> uses F::E {
        match self {
            Self::Some(value) => Option::Some(func(value))
            Self::None => Option::None
        }
    }

    pub fn and_then<U, F: Fn(own T) -> Option<U>>(own self, _ func: F) -> Option<U> uses F::E {
        match self {
            Self::Some(value) => func(value)
            Self::None => Option::None
        }
    }

    pub fn ok_or<E>(own self, _ err: own E) -> Result<E, T> {
        match self {
            Self::Some(value) => Result::Ok(value)
            Self::None => Result::Err(err)
        }
    }

    pub fn ok_or_else<E, F: Fn() -> E>(own self, _ err_func: F) -> Result<E, T> uses F::E {
        match self {
            Self::Some(value) => Result::Ok(value)
            Self::None => Result::Err(err_func())
        }
    }

    pub fn unwrap(own self) -> T {
        match self {
            Self::Some(t) => t
            Self::None => panic()
        }
    }

    pub fn unwrap_or(own self, default: own T) -> T {
        match self {
            Self::Some(x) => x
            Self::None => default
        }
    }

    pub fn unwrap_or_else<F: Fn() -> T>(own self, _ default_func: F) -> T uses F::E {
        match self {
            Self::Some(value) => value
            Self::None => default_func()
        }
    }

    pub fn take(mut self) -> Option<T> {
        replace(mut self, Option::None)
    }
}

impl<T> Option<T> where T: Default {
    pub fn unwrap_or_default(own self) -> T {
        match self {
            Self::Some(x) => x
            Self::None => T::default()
        }
    }
}

impl<T> Default for Option<T> {
    fn default() -> Self {
        Self::None
    }
}

impl Functor for Option {
    fn map<T, U, F: Fn(own T) -> U>(self: own Self<T>, _ func: F) -> Self<U> uses F::E {
        match self {
            Option::Some(value) => Option::Some(func(value))
            Option::None => Option::None
        }
    }
}

impl Applicative for Option {
    fn pure<T>(_ value: own T) -> Self<T> {
        Option::Some(value)
    }

    fn ap<T, U, F: Fn(own T) -> U>(self: own Self<F>, _ value: own Self<T>) -> Self<U> uses F::E {
        match (self, value) {
            (Option::Some(func), Option::Some(arg)) => Option::Some(func(arg))
            _ => Option::None
        }
    }
}

impl Monad for Option {
    fn bind<T, U, F: Fn(own T) -> Self<U>>(self: own Self<T>, _ func: F) -> Self<U> uses F::E {
        match self {
            Option::Some(value) => func(value)
            Option::None => Option::None
        }
    }
}

