use super::ops::Eq
use super::bytes::{AsBytes, PackedBytes}

/// Fixed-size string utilities.
///
/// `String<N>` values are represented as a packed word and are left-padded with zero bytes.
/// The "effective length" of a string is defined as the number of bytes after removing leading
/// zero-padding from its `N`-byte representation.
impl<const N: usize> String<N> {
    /// Returns the fixed-width byte representation of this string (including padding).
    #[inline(always)]
    pub const fn as_bytes(self) -> PackedBytes<N> {
        <Self as AsBytes>::as_bytes(self)
    }

    /// Constructs a string from its packed fixed-width bytes, including left padding.
    #[inline(always)]
    pub const fn from_bytes(_ bytes: PackedBytes<N>) -> Self {
        if N == 0 { return 0 as Self }
        (bytes.word(0) >> (((32 - N) * 8) as u256)) as Self
    }

    /// Returns the effective (unpadded) length in bytes.
    pub const fn len(self) -> usize {
        let bytes = self.as_bytes()
        var i: usize = 0
        while i < N {
            if bytes[i] != 0 {
                return N - i
            }
            i += 1
        }
        0
    }
}

/// Concatenates two fixed-size strings using their effective (unpadded) lengths.
///
/// The result is left-padded with zeros to fill `OUT` bytes.
///
/// If `a.len() + b.len() > OUT`, the result is truncated on the right (i.e. it
/// keeps as much of `a` as possible, then as much of `b` as fits).
pub const fn concat<const A: usize, const B: usize, const OUT: usize>(
    _ a: String<A>,
    _ b: String<B>,
) -> String<OUT> {
    let a_len: usize = a.len()
    let b_len: usize = b.len()
    var a_take: usize = a_len
    if a_take > OUT {
        a_take = OUT
    }
    var b_take: usize = b_len
    if a_take + b_take > OUT {
        b_take = OUT - a_take
    }
    // Each kept prefix drops the trailing bytes that do not fit.
    let a_kept = padded_word(a) >> (((a_len - a_take) * 8) as u256)
    let b_kept = padded_word(b) >> (((b_len - b_take) * 8) as u256)
    ((a_kept << ((b_take * 8) as u256)) | b_kept) as String<OUT>
}

/// The string's word without the bits above its capacity.
const fn padded_word<const N: usize>(_ s: String<N>) -> u256 {
    (s as u256) & ((1 << ((N * 8) as u256)) - 1)
}

impl<const N: usize> Eq for String<N> {
    const fn eq(self, _ other: String<N>) -> bool {
        self.as_bytes() == other.as_bytes()
    }

    const fn ne(self, _ other: String<N>) -> bool {
        !self.eq(other)
    }
}

