// Custom-width Solidity integers are always single static ABI words.
impl<T: SolInt> AbiSize for T {
    const HEAD_SIZE: u256 = 32
    const IS_DYNAMIC: bool = false
}

impl<T: SolInt> StaticAbiElement for T {}
impl<T: SolInt> StaticAbiElementSeal for T {}

impl<T: SolInt, A: Abi> AbiSpan<A> for T {
    fn payload_end<I: core::abi::ByteInput>(_: I, base: u256, pos: u256) -> u256 { pos + 32 }
}

// Mapping keys encode like `abi.encode` (sign-extended for signed widths),
// matching Solidity's `mapping(intN => V)` slot derivation.
impl<T: SolWordRepr + SolInt> StorageKey for T {
    fn encoded_len(self) -> u256 {
        32
    }

    unsafe fn write_key(ptr: *u8, self) {
        store_word(ptr: ptr, value: self.canonical_word())
    }
}

// `abi.encodePacked` uses the type's exact byte width, e.g. 3 bytes for int24.
impl<T: SolWordRepr + SolInt> EncodePacked for T {
    #[inline(always)]
    fn packed_width(self) -> u256 {
        T::BITS / 8
    }

    fn pack_into(own self, var _ p: own Packed) -> Packed {
        p.append_word(value: self.canonical_word(), width: T::BITS / 8)
        p
    }
    #[inline(always)]
    unsafe fn write_packed(own self, _ dest: *u8, room: u256) -> u256 {
        write_word_prefix(dest, self.canonical_word(), T::BITS / 8, room)

    }
}

impl<T: SolWordRepr + SolInt> TopicValue for T {
    fn as_topic(self) -> u256 { self.canonical_word() }
}

// Solidity packs custom-width ints into `BITS` bits of a storage slot.
impl<T: SolWordRepr + SolWrappingInt + SolInt> SolPacked for T {
    const BITS: u256 = T::BITS
    fn to_packed(own self) -> u256 {
        self.canonical_word()
    }
    fn from_packed(_ bits: u256) -> Self {
        T::from_wrapping_word(bits)
    }
}

