pub trait StaticAbiElement: StaticAbiElementSeal {}

const fn decimal_digits(value: usize) -> usize {
    var remaining = value
    var digits: usize = 1
    while remaining >= 10 {
        remaining /= 10
        digits += 1
    }
    digits
}

