        out.push_byte(91)
        var remaining = LEN
        var divisor: usize = 1
        while remaining >= 10 {
            remaining /= 10
            divisor *= 10
        }
        remaining = LEN
        while divisor != 0 {
            out.push_byte((48 + remaining / divisor).downcast_unchecked())
            remaining %= divisor
            divisor /= 10
        }
        out.push_byte(93)
    }
