use core::ByteWriter
use core::AsBytes
use core::abi::{
    Abi,
    AbiDecoder,
    AbiFrame,
    AbiSize,
    AbiSpan,
    ByteInput,
    Bytes,
    Decode,
    DynString,
    Encode,
}
use core::num::IntDowncast
use ingot::abi::DynArray
use ingot::evm::Address
use ingot::evm::TopicValue
use ingot::evm::ops::revert_empty

/// Maps a Fe type to its Solidity ABI type name.
///
/// The compiler uses this trait to build event signatures at compile time.
/// For example, `u256::SOL_TYPE` is `"uint256"` and `Address::SOL_TYPE` is
/// `"address"`. The `#[event]` desugaring generates a `TOPIC0` constant
/// from these values:
///
/// ```
/// const TOPIC0: u256 = keccak((Transfer::SOL_TYPE, "(", Address::SOL_TYPE, ",", u256::SOL_TYPE, ")"))
/// ```
///
/// Implement this trait for custom types to use them as event fields.
pub trait SolCompat {
    type S: AsBytes
    const SOL_TYPE: Self::S
}

/// Marker for Solidity ABI values encoded as one static 32-byte word.
///
/// This excludes dynamic values (`Bytes`, `DynString`, and arrays) as well as
/// static composites whose ABI head occupies more than one word.
pub(ingot) trait StaticAbiElementSeal {}

pub trait StaticAbiElement: StaticAbiElementSeal {}

const fn decimal_digits(value: usize) -> usize {
    var remaining = value
    var digits: usize = 1
    while remaining >= 10 {
        remaining /= 10
        digits += 1
    }
    digits
}

struct SolArraySuffix<const LEN: usize> {}

impl<const LEN: usize> AsBytes for SolArraySuffix<LEN> {
    const N: usize = decimal_digits(value: LEN) + 2

    #[inline(always)]
    const fn append_to<const M: usize>(self, _ out: mut ByteWriter<M>) {
        out.push_byte(91)
        var remaining = LEN
        var divisor: usize = 1
        while remaining >= 10 {
            remaining /= 10
            divisor *= 10
        }
        remaining = LEN
        while divisor != 0 {
            out.push_byte((48 + remaining / divisor).downcast_unchecked())
            remaining %= divisor
            divisor /= 10
        }
        out.push_byte(93)
    }
}

/// One byte of punctuation in a Solidity type name. The `SolCompat`
/// implementation of an `#[abi]` struct spells its fields' tuple type as
/// `("(", F0::SOL_TYPE, ",", F1::SOL_TYPE, ")")` with this type for the
/// punctuation, e.g. `(uint256,address)`.
pub type SolPunctuation = String<1>

impl<T, const LEN: usize> SolCompat for [T; LEN] where T: SolCompat {
    type S = (T::S, SolArraySuffix<LEN>)
    const SOL_TYPE: Self::S = (T::SOL_TYPE, SolArraySuffix<LEN> {})
