//! Ethereum address formatting and parsing.
use core::abi::DynString
use core::option::Option
use core::ptr
use core::text
use super::effects::Address
use super::crypto::keccak256

/// Format an address as `0x` and 40 ERC-55 checksum-cased hex digits.
/// This is the chain-independent ERC-55 encoding, not the ERC-1191 variant.
/// Specification: https://eips.ethereum.org/EIPS/eip-55
pub fn checksum_address(_ address: Address) -> DynString {
    let lower = text::hex(address.inner, 20)
    let hash = keccak256(lower.payload_span())
    let data = ptr::alloc_bytes(42)
    unsafe {
        *data = 48
        *ptr::offset_bytes(data, 1) = 120
    }
    let digits = ptr::offset_bytes(data, 2)
    for i in 0..40 {
        let digit = lower.byte_at(i)
        let uppercase = digit >= 97 && ((hash >> ((63 - i as u256) * 4)) & 15) >= 8
        let cased = if uppercase { digit - 32 } else { digit }
        unsafe { *ptr::offset_bytes(digits, i as u256) = cased }
    }
    unsafe { DynString::from_payload(source: ptr::MemSpan::from_raw_parts(ptr: data, len: 42)) }
}

/// Parses `0x` and 40 hex digits, or the 40 digits alone, as an address
/// (Solidity `Strings.tryParseAddress`). Digits of either case are accepted
/// and the ERC-55 checksum is not verified; compare the input with
/// `checksum_address` of the result to require it. `None` for any other
/// length or an invalid digit.
pub fn parse_address(_ text: DynString) -> Option<Address> {
    let len = text.len()
    let prefixed = len >= 2 && text.byte_at(0) == 48 && text.byte_at(1) == 120
    if len != (if prefixed { 42 } else { 40 }) {
        return Option::None
    }
    match text::parse_hex_uint(text) {
        Option::Some(inner) => Option::Some(Address { inner })
        Option::None => Option::None
    }
}

