impl Copy for CallData {}
impl Snapshot for CallData {}

impl CallData {
    #[inline(always)]
    pub fn new() -> Self {
        CallData { base: 0 }
    }

    #[inline(always)]
    pub fn with_base(_ base: u256) -> Self {
        CallData { base }
    }

