// -----------------------------------------------------------------------------
// Value types
// -----------------------------------------------------------------------------

/// EVM address (20 bytes).
///
/// Represented as a single `u256` ABI word with the address in the low 160
/// bits and every higher bit zero, as the EVM and Solidity see an address. An
/// address is built with `new`, which checks the word, or `from_word_truncate`,
/// so two equal addresses always have the same word: as storage keys, topics
/// and encodings.
pub struct Address { pub(ingot) inner: u256 }

impl Address {
    /// The address `word`, which must have no bits above the low 160. Fails
    /// with `Panic(0x11)` otherwise, at compile time for a constant.
    pub const fn new(_ word: u256) -> Self {
        if word >> 160 != 0 {
            core::panic_code(PANIC_OVERFLOW)
        }
        Address { inner: word }
    }

    pub fn zero() -> Self {
        Address { inner: 0 }
    }

    /// The address in the low 160 bits of `word`, like Solidity's
    /// `address(uint160(word))`. Higher bits are discarded.
    pub const fn from_word_truncate(_ word: u256) -> Self {
        Address { inner: word & 0xffffffffffffffffffffffffffffffffffffffff }
    }

    /// The address's ABI word: the address in the low 160 bits.
    pub const fn word(self) -> u256 {
        self.inner
    }
}

impl core::ops::Eq for Address {
    const fn eq(self, _ other: Address) -> bool {
        self.inner == other.inner
    }
}

impl Copy for Address {}
impl Snapshot for Address {}

/// Orders addresses by their numeric value, like Solidity's `<` on
/// `address`, so signer lists can be sorted and checked for duplicates.
impl core::ops::Ord for Address {
    const fn lt(self, _ other: Address) -> bool {
        self.inner < other.inner
    }
    const fn le(self, _ other: Address) -> bool {
        self.inner <= other.inner
    }
    const fn gt(self, _ other: Address) -> bool {
        self.inner > other.inner
    }
    const fn ge(self, _ other: Address) -> bool {
        self.inner >= other.inner
    }
}

impl Default for Address {
    fn default() -> Self {
        Address::zero()
    }
}

impl AbiSize for Address {
    const HEAD_SIZE: u256 = 32
    const IS_DYNAMIC: bool = false
}

impl<A: Abi> Decode<A> for Address {
    #[inline(always)]
    fn decode_payload<D: AbiDecoder<A>, I: ByteInput>(_ d: mut D, _ input: I) -> Self {
        let word = d.read_word(input)
        if word >> 160 != 0 {
            ops::revert_empty()
        }
        Address { inner: word }
    }

    #[inline(always)]
    fn decode_from<I: ByteInput>(_ input: I, _ pos: u256) -> Self {
        let word = input.word_at(pos)
        if word >> 160 != 0 {
            ops::revert_empty()
        }
        Address { inner: word }
    }
}

impl<A: Abi> Encode<A> for Address {
    #[inline(always)]
    fn encode(own self, _ out: AbiFrame) {
        out.store_word(at: 0, value: self.inner)
    }
}

impl<A: Abi> AbiSpan<A> for Address {
    fn payload_end<I: core::abi::ByteInput>(_: I, base: u256, pos: u256) -> u256 {
        pos + 32
    }
}

// -----------------------------------------------------------------------------
// Raw pointers
// -----------------------------------------------------------------------------

/// Pointers into storage, transient storage and calldata. Each is its address
/// word; `*p`, in an `unsafe` context, is the `T` there.
pub use core::ptr::{CalldataPtr, StorPtr, TStorPtr}

/// A transient storage cell holding a `T`, kept in a storage struct.
///
/// A `TSlot` is pinned to transient storage: its value lies there from the
/// cell's number on, taking as many numbers as it has words, and the layout
/// keeps them apart from other transient state. `slot.value` is the value's
/// place.
pub struct TSlot<T> {
    pub value: T,
}

impl<T> Pinned for TSlot<T> {
    type Space = Transient
}

impl<T> TSlot<T> {
    /// Reads the value.
    pub fn read(self) -> T
        where T: Copy
    {
        self.value
    }

    /// Writes the value.
    pub fn write(mut self, _ value: own T) {
        self.value = value
    }

    /// Zeroes the value.
    pub fn clear(mut self)
        where T: Clearable
    {
        // Transient storage starts zeroed, so zero is a value of every
        // clearable `T` there.
        unsafe { clear(mut self.value) }
    }
}

