/// The selector followed by the message's ABI payload, encoded in place in
/// one allocation.
#[arithmetic(unchecked)]
#[inline(always)]
fn encode_calldata<M>(_ selector: u32, _ message: own M) -> MemBuffer
where M: Encode<Sol>
{
    let selector_size = size_of<Sol::Selector>()
    let payload_size = abi_payload_size(message)
    let buffer = unsafe { MemBuffer::alloc_uninit(selector_size as usize + payload_size as usize) }
    let payload = ptr::offset_bytes(buffer.ptr(), selector_size)
    unsafe {
        // The selector word's low bytes are overwritten by the payload, or
        // lie past the buffer's end in unallocated memory.
        ops::mstore(addr: buffer.ptr(), value: (selector as u256) << 224)
        // The payload bytes, zeroed for the encoding to fill.
        ptr::zero_bytes(payload, payload_size)
        message.encode(AbiFrame::from_raw_parts(ptr: payload, len: payload_size))
    }
    buffer
}

/// ABI-encode a message (4-byte selector + payload) into freshly allocated
/// memory without performing a call.
pub fn encode_msg_calldata<M>(_ message: own M) -> MemBuffer
where M: MsgVariant<Sol> + Encode<Sol>
{
    encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
}

/// Copy the complete current returndata into a fresh owner.
pub fn copy_returndata() -> MemBuffer {
    let ret_len = ops::returndatasize()
    let buffer = unsafe { MemBuffer::alloc_uninit(ret_len as usize) }
    unsafe { ops::returndatacopy(dest: buffer.ptr(), offset: 0, len: ret_len) }
    buffer
}

/// Revert, bubbling the current returndata payload unchanged.
pub fn bubble_last_revert() -> ! {
    let ret = copy_returndata()
    unsafe { ops::revert(offset: ret.ptr(), len: ret.len() as u256) }
}

/// Revert with the current returndata if there is any, otherwise with the
/// custom error `error`.
///
/// This is OpenZeppelin's `Address.verifyCallResult` fallback: after a failed
/// call, a callee's reason (custom error, `Error(string)`, `Panic`, raw bytes)
/// is bubbled unchanged, and a callee that reverted without data (or a
/// failure with no returndata, such as a call running out of gas) gets a
/// descriptive error instead of an empty revert. The returndata is read
/// directly from the EVM; the current returndata must be the failed call's.
pub fn bubble_revert_or<E>(_ error: own E) -> !
    where E: ErrorVariant<Sol> + Encode<Sol>
{
    if ops::returndatasize() == 0 {
        revert_error(error)
    }
    bubble_last_revert()
}

/// Decode Solidity ABI data from an in-memory returndata buffer.
pub fn decode_returndata<R>(_ ret: MemSpan) -> R
    where R: Decode<Sol> + AbiSize
{
    decode_output(ret)
}

/// Perform a raw `STATICCALL` and ABI-decode the returndata on success.
///
/// This bubbles revert data on call failure and reuses the regular Solidity
/// decoder, so short or non-canonical returndata also reverts.
/// Shared call authority accounts for read-only reentry into contract state.
pub fn staticcall_decode<R>(addr: Address, gas: u256, args: MemSpan) -> R
    uses (call: Call)
    where R: Decode<Sol> + AbiSize
{
    var ret = MemBuffer::empty()
    let outcome = call.raw_staticcall(addr, gas, args, ret: mut ret)
    if !outcome.success() {
        bubble_last_revert()
    }

    decode_returndata(copy_returndata().span())
}

