impl ContractHost for Evm {
    type Input = CallData
    type InitInput = MemSpan

    fn input(self) -> Self::Input {
        CallData::new()
    }

    fn init_input<F>(mut self, _ runtime: F) -> ref Self::InitInput {
        let offset = self.code_region_offset(runtime)
        let len = self.code_region_len(runtime)
        let args_offset = offset + len
        let code_size = self.codesize()
        if code_size < args_offset {
            self.abort()
        }
        let args_len = code_size - args_offset
        var args = MemBuffer::alloc(args_len as usize)
        self.codecopy(
            dest: mut args,
            dest_offset: 0,
            src_offset: args_offset,
            len: args_len,
        )
        args.span()
    }

    fn create_contract<F>(mut self, _ runtime: F) -> ! {
        let len = self.code_region_len(runtime)
        let offset = self.code_region_offset(runtime)
        var buffer = MemBuffer::alloc(len as usize)
        self.codecopy(
            dest: mut buffer,
            dest_offset: 0,
            src_offset: offset,
            len,
        )
        self.return_data(data: buffer.span())
    }

    fn abort(self) -> ! {
        ops::revert_empty()
    }

    fn return_bytes(self, data: MemSpan) -> ! {
        self.return_data(data)
    }

    fn return_value<A: Abi, T>(mut self, _ value: own T) -> !
        where T: Encode<A> + AbiSize
    {
        if !T::IS_DYNAMIC {
            // Each fresh buffer is zeroed, and only the encoding writes it.
            if T::HEAD_SIZE <= 32 {
                let out = ptr::FixedMemBuffer<32>::alloc()
                unsafe {
                    value.encode(AbiFrame::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE))
                    self.return_data(
                        data: MemSpan::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE as usize),
                    )
                }
            } else if T::HEAD_SIZE <= 64 {
                let out = ptr::FixedMemBuffer<64>::alloc()
                unsafe {
                    value.encode(AbiFrame::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE))
                    self.return_data(
                        data: MemSpan::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE as usize),
                    )
                }
            } else {
                let out = MemBuffer::alloc(T::HEAD_SIZE as usize)
                value.encode(unsafe { AbiFrame::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE) })
                self.return_data(data: out.span())
            }
        } else {
            let out = encode_return_alloc<A, T>(value)
            self.return_bytes(data: out.span())
        }
    }
}

/// EVM address (20 bytes).
///
/// Represented as a single `u256` ABI word with the address in the low 160
/// bits and every higher bit zero, as the EVM and Solidity see an address. An
/// address is built with `new`, which checks the word, or `from_word_truncate`,
/// so two equal addresses always have the same word: as storage keys, topics
/// and encodings.
pub struct Address { pub(ingot) inner: u256 }

trait_impls.signature:
/// Orders addresses by their numeric value, like Solidity's `<` on
/// `address`, so signer lists can be sorted and checked for duplicates.
impl core::ops::Ord for Address

