/// A transient storage cell holding a `T`, kept in a storage struct.
///
/// A `TSlot` is pinned to transient storage: its value lies there from the
/// cell's number on, taking as many numbers as it has words, and the layout
/// keeps them apart from other transient state. `slot.value` is the value's
/// place.
pub struct TSlot<T> {
    pub value: T,
}

/// Low-level raw storage operations.
///
/// A raw slot must not belong to anything the compiler allocated, such as a
/// contract field: the access checker does not see accesses through it. The
/// same authority covers `*p` of a storage pointer, `slot as StorPtr<T>`.
pub trait RawStorage: EvmCapabilitySeal {
    unsafe fn sload(self, _: u256) -> u256
    unsafe fn sstore(mut self, slot: u256, value: u256)
}

/// The `T` at storage slot `slot`, as a storage place to read, or to write
/// where its use asks for `mut`.
///
/// The caller must ensure that `slot` holds a `T` and that nothing the
/// compiler allocates, such as a contract field, uses `slot` or the slots the
/// `T` derives from it.
#[raw_place]
pub unsafe fn storage_at<T>(_ slot: u256) -> mut? T uses (storage: mut? RawStorage) {
    unsafe { mut? *(slot as StorPtr<T>) }
}

/// Copies one word from the current contract's persistent storage.
///
/// Any slot is permitted, including declared contract state. Shared raw
/// authority reserves state for reading, so the access checker rejects this
/// call while a conflicting mutable access is live. The returned word is an
/// independent value; no typed storage place or ownership claim escapes.
#[inline(always)]
pub fn read_storage_word(_ slot: u256) -> u256 uses (storage: RawStorage) {
    unsafe { ops::sload(slot) }
}

/// Copies one word from the current contract's transaction-local storage.
///
/// This has the same authority and interference rules as `read_storage_word`.
/// Every word is a valid `u256`. The internal pointer stays within this read;
/// callers receive neither a pointer nor authority to write its slot.
#[inline(always)]
pub fn read_transient_word(_ slot: u256) -> u256 uses (storage: RawStorage) {
    unsafe { *(slot as TStorPtr<u256>) }
}

/// Access to low-level EVM op functions (excluding raw stack ops).
pub trait RawOps: RawStorage {
    fn calldataload(self, _: u256) -> u256
    fn calldatasize(self) -> u256
    /// The caller must ensure that a valid `T` is encoded at `offset`.
    unsafe fn calldata_ptr<T>(self, _ offset: u256) -> CalldataPtr<T> {
        offset as CalldataPtr<T>
    }
    fn calldatacopy(
        mut self,
        dest: mut MemBuffer,
        dest_offset: u256,
        src_offset: u256,
        len: u256,
    )

    fn returndatasize(self) -> u256
    fn returndatacopy(
        mut self,
        dest: mut MemBuffer,
        dest_offset: u256,
        src_offset: u256,
        len: u256,
    )

    fn codecopy(
        mut self,
        dest: mut MemBuffer,
        dest_offset: u256,
        src_offset: u256,
        len: u256,
    )
    fn codesize(self) -> u256

    fn keccak256(self, data: MemSpan) -> u256

    fn revert(self, data: MemSpan) -> !

    fn return_data(self, data: MemSpan) -> !

    fn code_region_offset<F>(self, _: F) -> u256
    fn code_region_len<F>(self, _: F) -> u256
}

pub trait Log: EvmCapabilitySeal {
    fn log0(mut self, data: MemSpan)

    fn log1(mut self, data: MemSpan, topic0: u256)

    fn log2(mut self, data: MemSpan, topic0: u256, topic1: u256)

    fn log3(mut self, data: MemSpan, topic0: u256, topic1: u256, topic2: u256)

    fn log4(mut self, data: MemSpan, topic0: u256, topic1: u256, topic2: u256, topic3: u256)

    /// Emit a Solidity-compatible event log (`log1`-`log4`).
    ///
    /// This delegates to the `std::evm::Event` implementation generated for
    /// `#[event]` structs.
    #[inline(always)]
    fn emit<E>(mut self, _ event: own E)
        where E: super::event::Event
    {
        event.emit(mut self)
    }
}

/// Metadata for deployable high-level contracts.
///
/// The compiler synthesizes an implementation of this trait for each high-level
/// `contract` item, enabling typed `CREATE`/`CREATE2` from within other
/// contracts.
pub trait Contract {
    /// Constructor argument tuple, ABI-encodable under the default ABI.
    type InitArgs: Encode<Sol>

    /// Offset of this contract's initcode within the current artifact.
    fn init_code_offset() -> u256

    /// Length (in bytes) of this contract's initcode within the current artifact.
    fn init_code_len() -> u256
}

pub trait Create: EvmCapabilitySeal {
    /// Low-level `CREATE` opcode.
    fn create_raw(mut self, value: Wei, init_code: MemSpan) -> Address {
        unsafe { Address { inner: ops::create(value: value.as_wei(), offset: init_code.ptr(), len: init_code.len() as u256) } }
    }

    /// Low-level `CREATE2` opcode.
    fn create2_raw(mut self, value: Wei, init_code: MemSpan, salt: u256) -> Address {
        unsafe {
            Address {
                inner: ops::create2(value: value.as_wei(), offset: init_code.ptr(), len: init_code.len() as u256, salt: salt),
            }
        }
    }

    /// Deploy a high-level contract using `CREATE`, bubbling revert data on failure.
    fn create<C: Contract>(mut self, value: Wei, args: own C::InitArgs) -> Address {
        let init_code = contract_init_code<C>(args)
        let addr = self.create_raw(value: value, init_code: init_code.span())

        // Solidity-style behavior: bubble revert data if creation fails.
        if addr.inner == 0 {
            bubble_last_revert()
        }

        addr
    }

    /// Deploy a high-level contract using `CREATE2`, bubbling revert data on failure.
    fn create2<C: Contract>(mut self, value: Wei, args: own C::InitArgs, salt: u256) -> Address {
        let init_code = contract_init_code<C>(args)
        let addr = self.create2_raw(value: value, init_code: init_code.span(), salt)

        // Solidity-style behavior: bubble revert data if creation fails.
        if addr.inner == 0 {
            bubble_last_revert()
        }

        addr
    }
}

#[inline(always)]
pub fn encode_abi_payload<T>(_ value: own T) -> MemBuffer
    where T: Encode<Sol> + AbiSize
{
    encode_alloc<Sol, T>(value)
}

/// Init code that `create<C>` and `create2<C>` deploy: `C`'s creation code
/// embedded in the current contract, followed by the ABI-encoded `args`
/// (nothing is appended when `C::InitArgs` encodes to zero bytes, e.g. `()`).
#[inline(always)]
fn contract_init_code<C: Contract>(_ args: own C::InitArgs) -> MemBuffer {
    let init_len = C::init_code_len()
    let init_off = C::init_code_offset()
    if !C::InitArgs::IS_DYNAMIC && C::InitArgs::HEAD_SIZE == 0 {
        let init_code = unsafe { MemBuffer::alloc_uninit(init_len as usize) }
        unsafe { ops::codecopy(dest: init_code.ptr(), offset: init_off, len: init_len) }
        init_code
    } else {
        let encoded = encode_abi_payload<C::InitArgs>(args)
        let init_code = unsafe { MemBuffer::alloc_uninit(init_len as usize + encoded.len()) }
        unsafe {
            ops::codecopy(dest: init_code.ptr(), offset: init_off, len: init_len)
            ptr::copy(
                dest: ptr::offset_bytes(init_code.ptr(), init_len),
                source: encoded.span(),
            )
        }
        init_code
    }
}

/// Keccak256 of the init code `create2<C>(value, args, salt)` deploys: `C`'s
/// creation code as embedded in the current contract, followed by the
/// ABI-encoded constructor `args` (pass `()` for a contract whose `init`
/// takes no arguments).
///
/// This is the `init_code_hash` input of `create2_address`. The creation code
/// is copied to fresh memory with `CODECOPY` and hashed there, so the cost
/// grows with its size (about 9 gas per 32-byte word plus memory expansion,
/// on top of encoding `args`). Contracts that derive many addresses usually
/// compute the hash once, e.g. in `init`, and store it.
pub fn init_code_hash<C: Contract>(_ args: own C::InitArgs) -> u256 {
    let init_code = contract_init_code<C>(args)
    unsafe { ops::keccak256(offset: init_code.ptr(), len: init_code.len() as u256) }
}

/// Address at which `create2<C>(value, args, salt)` executed by `deployer`
/// creates the contract: `create2_address(deployer, salt, init_code_hash<C>(args))`.
///
/// The deployment itself may still fail (e.g. the address already holds code,
/// or `C`'s `init` reverts); this only derives the address.
pub fn predict_create2<C: Contract>(deployer: Address, args: own C::InitArgs, salt: u256) -> Address {
    super::crypto::create2_address(deployer, salt, init_code_hash: init_code_hash<C>(args))
}

/// Metadata returned by a low-level EVM call.
#[must_use]
pub struct RawCallOutcome {
    success: bool,
    returndata_len: u256,
}

/// Owned returndata from a typed, non-bubbling EVM call.
///
/// The payload is preserved for both success and failure, so callers can
/// inspect or decode it without relying on the ephemeral returndata buffer.
#[must_use]
pub struct CallOutcome {
    success: bool,
    returndata: MemBuffer,
}

fn finish_raw_call(_ success: bool, _ ret: mut MemBuffer) -> RawCallOutcome {
    let returndata_len = ops::returndatasize()
    let written = if returndata_len < ret.capacity() as u256 {
        returndata_len as usize
    } else {
        ret.capacity()
    }
    unsafe { ret.set_len(written) }
    RawCallOutcome {
        success,
        returndata_len,
    }
}

fn copy_call_outcome(_ raw: RawCallOutcome) -> CallOutcome {
    CallOutcome {
        success: raw.success(),
        returndata: copy_returndata(),
    }
}

