fn prepare_copy_destination(
    dest: mut MemBuffer,
    dest_offset: u256,
    len: u256,
) -> *u8 {
    if dest_offset > dest.capacity() as u256 || len > dest.capacity() as u256 - dest_offset {
        core::panic()
    }
    if len != 0 && dest_offset > dest.len() as u256 {
        unsafe {
            ptr::zero_bytes(
                ptr: ptr::offset_bytes(dest.ptr(), dest.len() as u256),
                len: dest_offset - dest.len() as u256,
            )
        }
    }
    ptr::offset_bytes(dest.ptr(), dest_offset)
}

/// High-level contract calls with ABI encoding/decoding.
pub trait Call: EvmCapabilitySeal {
    /// Low-level `CALL` opcode with explicit input and output regions.
    ///
    /// The output buffer receives at most its capacity; the outcome retains
    /// the full returndata length.
    fn raw_call(
        mut self,
        addr: Address,
        gas: u256,
        value: Wei,
        args: MemSpan,
        ret: mut MemBuffer,
    ) -> RawCallOutcome {
        let success = unsafe {
            ops::call(
                gas: gas,
                addr: addr.inner,
                value: value.as_wei(),
                args_offset: args.ptr(),
                args_len: args.len() as u256,
                ret_offset: ret.ptr(),
                ret_len: ret.capacity() as u256,
            ) != 0
        }
        finish_raw_call(success, mut ret)
    }

    /// Call with an explicit gas allotment and a caller reserve. An Err means
    /// the budget was insufficient and no external call was made. Ok contains
    /// EVM success/failure; it does not imply target code exists.
    ///
    /// Input is copied before measuring gas to pay memory expansion up front.
    /// No returndata is copied, so an adversarial return cannot consume the
    /// reserve. The outcome reports its full length. Revert data is not bubbled.
    ///
    /// See calls::has_min_gas for the EIP-150 admission rule and gas-schedule
    /// assumptions. The requested gas is forwarded exactly (plus the EVM's
    /// value stipend); admission is conservative and may reject feasible calls.
    fn call_with_min_gas(
        mut self,
        addr: Address,
        minimum: u256,
        reserved: u256,
        value: Wei,
        args: MemSpan,
    ) -> Result<super::calls::InsufficientGas, RawCallOutcome> {
        let input = MemBuffer::from_span(args)
        var output = MemBuffer::empty()
        if !super::calls::has_min_gas(ops::gas(), minimum, reserved) {
            return Result::Err(super::calls::InsufficientGas {})
        }
        Result::Ok(
            self.raw_call(
                addr,
                gas: minimum,
                value,
                args: input.span(),
                ret: mut output,
            ),
        )
    }

    /// Low-level `STATICCALL` opcode with explicit input and output buffers.
    ///
    /// The output buffer receives at most its capacity; the outcome retains
    /// the full returndata length.
    fn raw_staticcall(
        self,
        addr: Address,
        gas: u256,
        args: MemSpan,
        ret: mut MemBuffer,
    ) -> RawCallOutcome {
        let success = unsafe {
            ops::staticcall(
                gas: gas,
                addr: addr.inner,
                args_offset: args.ptr(),
                args_len: args.len() as u256,
                ret_offset: ret.ptr(),
                ret_len: ret.capacity() as u256,
            ) != 0
        }
        finish_raw_call(success, mut ret)
    }

    /// Low-level `DELEGATECALL` opcode with explicit input and output buffers.
    ///
    /// The output buffer receives at most its capacity; the outcome retains
    /// the full returndata length.
    fn raw_delegatecall(
        mut self,
        addr: Address,
        gas: u256,
        args: MemSpan,
        ret: mut MemBuffer,
    ) -> RawCallOutcome {
        let success = unsafe {
            ops::delegatecall(
                gas: gas,
                addr: addr.inner,
                args_offset: args.ptr(),
                args_len: args.len() as u256,
                ret_offset: ret.ptr(),
                ret_len: ret.capacity() as u256,
            ) != 0
        }
        finish_raw_call(success, mut ret)
    }

    /// `CALL` with pre-encoded calldata without bubbling failure.
    ///
    /// The returned owner contains the complete success or revert payload.
    fn try_call_raw(mut self, addr: own Address, gas: u256, value: Wei, args: MemSpan) -> CallOutcome {
        var ret = MemBuffer::empty()
        let raw = self.raw_call(addr, gas, value, args, ret: mut ret)
        copy_call_outcome(raw)
    }

    /// Perform a typed `CALL` without bubbling failure.
    ///
    /// The returned owner contains the complete success or revert payload.
    fn try_call<M>(
        mut self,
        addr: own Address,
        gas: u256,
        value: Wei,
        message: own M,
    ) -> CallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        var ret = MemBuffer::empty()
        let raw = self.raw_call(addr, gas, value, args: args.span(), ret: mut ret)
        copy_call_outcome(raw)
    }

    /// Perform a typed `STATICCALL` without bubbling failure.
    fn try_static<M>(self, addr: own Address, gas: u256, message: own M) -> CallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        var ret = MemBuffer::empty()
        let raw = self.raw_staticcall(addr, gas, args: args.span(), ret: mut ret)
        copy_call_outcome(raw)
    }

    /// Send `value` to `addr` with empty calldata (Solidity
    /// `addr.call{value: value}("")`), without copying returndata or
    /// bubbling failure.
    fn send_value(mut self, addr: own Address, gas: u256, value: Wei) -> RawCallOutcome {
        var ret = MemBuffer::empty()
        self.raw_call(addr, gas, value, args: MemSpan::empty(), ret: mut ret)
    }

    /// Perform a typed `CALL`, copying at most `ret.capacity()` bytes of
    /// returndata into `ret` without bubbling failure.
    ///
    /// Bounding the copy protects against callees that return oversized data.
    /// The outcome still reports the full returndata length.
    fn try_call_into<M>(
        mut self,
        addr: own Address,
        gas: u256,
        value: Wei,
        message: own M,
        ret: mut MemBuffer,
    ) -> RawCallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        self.raw_call(addr, gas, value, args: args.span(), ret: mut ret)
    }

    /// Perform a typed `STATICCALL`, copying at most `ret.capacity()` bytes of
    /// returndata into `ret` without bubbling failure.
    fn try_static_into<M>(
        self,
        addr: own Address,
        gas: u256,
        message: own M,
        ret: mut MemBuffer,
    ) -> RawCallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        self.raw_staticcall(addr, gas, args: args.span(), ret: mut ret)
    }

    /// Perform a typed `DELEGATECALL` without bubbling failure.
    fn try_delegate<M>(mut self, addr: own Address, gas: u256, message: own M) -> CallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        var ret = MemBuffer::empty()
        let raw = self.raw_delegatecall(addr, gas, args: args.span(), ret: mut ret)
        copy_call_outcome(raw)
    }

    fn call<M>(mut self, addr: own Address, gas: u256, value: Wei, message: own M) -> M::Return
    where M: MsgVariant<Sol> + Encode<Sol>, M::Return: Decode<Sol> + AbiSize
    {
        self.try_call(addr, gas, value, message).decode()
    }

    /// Like `call<M>`, but if the call succeeds with EMPTY returndata, returns
    /// `default` instead of reverting in the decoder. Reverts are still bubbled,
    /// and non-empty returndata is still decoded strictly.
    ///
    /// Caveat (same as Vyper's `default_return_value`): a call to an address
    /// with no code succeeds with empty returndata at the EVM level, so it
    /// yields `default`, a silent no-op "success". For ERC20 interactions use
    /// `std::evm::erc20`, which closes this hole with a code-existence check.
    fn call_with_default<M>(
        mut self,
        addr: own Address,
        gas: u256,
        value: Wei,
        message: own M,
        default: own M::Return,
    ) -> M::Return
    where M: MsgVariant<Sol> + Encode<Sol>, M::Return: Decode<Sol> + AbiSize
    {
        let outcome = self.try_call(addr, gas, value, message)
        if outcome.success() && outcome.returndata_len() == 0 {
            return default
        }
        outcome.decode()
    }

    fn static<M>(self, addr: own Address, gas: u256, message: own M) -> M::Return
    where M: MsgVariant<Sol> + Encode<Sol>, M::Return: Decode<Sol> + AbiSize
    {
        self.try_static(addr, gas, message).decode()
    }

    fn delegate<M>(mut self, addr: own Address, gas: u256, message: own M) -> M::Return
    where M: MsgVariant<Sol> + Encode<Sol>, M::Return: Decode<Sol> + AbiSize
    {
        self.try_delegate(addr, gas, message).decode()
    }
}

/// Default EVM effect provider (zero-sized).
///
/// Its seal is an `unsafe` field: an `Evm` is the authority the runtime
/// grants, which safe code cannot establish, so no zeroed or stored value
/// stands in for one.
pub struct Evm { unsafe seal: Private }

/// The selector followed by the message's ABI payload, encoded in place in
/// one allocation.
#[arithmetic(unchecked)]
#[inline(always)]
fn encode_calldata<M>(_ selector: u32, _ message: own M) -> MemBuffer
where M: Encode<Sol>
{
    let selector_size = size_of<Sol::Selector>()
    let payload_size = abi_payload_size(message)
    let buffer = unsafe { MemBuffer::alloc_uninit(selector_size as usize + payload_size as usize) }
    let payload = ptr::offset_bytes(buffer.ptr(), selector_size)
    unsafe {
        // The selector word's low bytes are overwritten by the payload, or
        // lie past the buffer's end in unallocated memory.
        ops::mstore(addr: buffer.ptr(), value: (selector as u256) << 224)
        // The payload bytes, zeroed for the encoding to fill.
        ptr::zero_bytes(payload, payload_size)
        message.encode(AbiFrame::from_raw_parts(ptr: payload, len: payload_size))
    }
    buffer
}

/// ABI-encode a message (4-byte selector + payload) into freshly allocated
/// memory without performing a call.
pub fn encode_msg_calldata<M>(_ message: own M) -> MemBuffer
where M: MsgVariant<Sol> + Encode<Sol>
{
    encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
}

/// Copy the complete current returndata into a fresh owner.
pub fn copy_returndata() -> MemBuffer {
    let ret_len = ops::returndatasize()
    let buffer = unsafe { MemBuffer::alloc_uninit(ret_len as usize) }
    unsafe { ops::returndatacopy(dest: buffer.ptr(), offset: 0, len: ret_len) }
    buffer
}

/// Revert, bubbling the current returndata payload unchanged.
pub fn bubble_last_revert() -> ! {
    let ret = copy_returndata()
    unsafe { ops::revert(offset: ret.ptr(), len: ret.len() as u256) }
}

/// Revert with the current returndata if there is any, otherwise with the
/// custom error `error`.
///
/// This is OpenZeppelin's `Address.verifyCallResult` fallback: after a failed
/// call, a callee's reason (custom error, `Error(string)`, `Panic`, raw bytes)
/// is bubbled unchanged, and a callee that reverted without data (or a
/// failure with no returndata, such as a call running out of gas) gets a
/// descriptive error instead of an empty revert. The returndata is read
/// directly from the EVM; the current returndata must be the failed call's.
pub fn bubble_revert_or<E>(_ error: own E) -> !
    where E: ErrorVariant<Sol> + Encode<Sol>
{
    if ops::returndatasize() == 0 {
        revert_error(error)
    }
    bubble_last_revert()
}

/// Decode Solidity ABI data from an in-memory returndata buffer.
pub fn decode_returndata<R>(_ ret: MemSpan) -> R
    where R: Decode<Sol> + AbiSize
{
    decode_output(ret)
}

/// Perform a raw `STATICCALL` and ABI-decode the returndata on success.
///
/// This bubbles revert data on call failure and reuses the regular Solidity
/// decoder, so short or non-canonical returndata also reverts.
/// Shared call authority accounts for read-only reentry into contract state.
pub fn staticcall_decode<R>(addr: Address, gas: u256, args: MemSpan) -> R
    uses (call: Call)
    where R: Decode<Sol> + AbiSize
{
    var ret = MemBuffer::empty()
    let outcome = call.raw_staticcall(addr, gas, args, ret: mut ret)
    if !outcome.success() {
        bubble_last_revert()
    }

    decode_returndata(copy_returndata().span())
}

#[inline(always)]
pub fn assert(_ b: own bool) {
    assert!(b)
}

/// Revert the current transaction with ABI-encoded data.
///
/// Encodes the given value using Solidity ABI encoding and reverts
/// with the encoded bytes as revert data.
pub fn revert<T>(_ value: own T) -> !
    where T: Encode<Sol> + AbiSize
{
    let result = encode_single_root_alloc<Sol, T>(value)
    unsafe { ops::revert(offset: result.ptr(), len: result.len() as u256) }
}

/// Revert with a Solidity-compatible custom error.
///
/// Encodes the error with its 4-byte selector prefix followed by
/// ABI-encoded fields, matching Solidity's custom error encoding.
///
/// Never inlined: a revert is a cold path, and one shared instance per error
/// type is smaller than a copy of the encoding at every call site.
#[inline(never)]
pub fn revert_error<T>(_ error: own T) -> !
    where T: ErrorVariant<Sol> + Encode<Sol>
{
    let buffer = encode_error(error)
    unsafe { ops::revert(offset: buffer.ptr(), len: buffer.len() as u256) }
}

/// Encode a custom error (4-byte selector + ABI-encoded fields) into freshly
/// allocated memory without reverting.
///
/// The bytes are exactly what `revert_error(error)` reverts with. Encode the
/// error ahead of time and revert later with `revert_bytes` when the revert
/// must be cheap, for example after a call that may burn all forwarded gas
/// and leave only the retained 1/64 for the failure path.
pub fn encode_error<T>(_ error: own T) -> MemBuffer
    where T: ErrorVariant<Sol> + Encode<Sol>
{
    encode_calldata(<T as ErrorVariant<Sol>>::SELECTOR, error)
}

/// Revert with `data` as the raw revert payload.
///
/// Use it to rethrow preserved revert data (for example
/// `CallOutcome::returndata()`) or bytes pre-encoded with `encode_error`.
pub fn revert_bytes(_ data: MemSpan) -> ! {
    unsafe { ops::revert(offset: data.ptr(), len: data.len() as u256) }
}

/// Revert without revert data, like Solidity's `revert()`.
pub fn revert_empty() -> ! {
    ops::revert_empty()
}

