    token: Address,
    owner: Address,
    receiver: Address,
    id: u256,
    amount: u256,
    data: Bytes,
) -> TokenCall
uses (ctx: Ctx, call: mut Call)
{
    if ctx.extcodesize(token) == 0 {
        return TokenCall::NoCode
    }
    var ret = MemBuffer::empty()
    let outcome = call.try_call_into(
        addr: token,
        gas: ops::gas(),
        value: Wei::zero(),
        message: Erc1155Msg::SafeTransferFrom { owner, receiver, id, amount, data },
        ret: mut ret,
    )
    if outcome.success() {
        TokenCall::Ok
