impl<const N: usize> EncodePacked for [u8; N] {
    #[inline(always)]
    fn packed_width(self) -> u256 { N as u256 }
    fn pack_into(own self, var _ p: own Packed) -> Packed {
        p.bytes(self)
        p
    }
    #[inline(always)]
    unsafe fn write_packed(own self, _ dest: *u8, room: u256) -> u256 {
        check_room(width: N as u256, room)
        var i: usize = 0
        while i < N {
            *ptr::offset_bytes(dest, i as u256) = self[i]
            i += 1
        }
        N as u256
    }
}

// N raw content bytes — see `Packed::fixed_bytes` for the alignment
// footgun.
impl<const N: usize> EncodePacked for FixedBytes<N> {
    #[inline(always)]
    fn packed_width(self) -> u256 { N as u256 }
    fn pack_into(own self, var _ p: own Packed) -> Packed {
        p.fixed_bytes(self)
        p
    }
    #[inline(always)]
    unsafe fn write_packed(own self, _ dest: *u8, room: u256) -> u256 {
        // Unsupported widths and non-canonical values revert, as in
        // `Packed::fixed_bytes`.
        if N == 0 || N > 32 || (N < 32 && self.val >> ((N as u256) * 8) != 0) {
            ops::revert_empty()
        }
        write_word_prefix(dest, self.val, N as u256, room)
    }
}

// `len()` raw payload bytes, no length word.
impl EncodePacked for Bytes {
    #[inline(always)]
    fn packed_width(self) -> u256 { self.len() as u256 }
    fn pack_into(own self, var _ p: own Packed) -> Packed {
        let source = self.payload_span()
        p.append_raw(source: source.ptr(), len: source.len() as u256)
        p
    }
    #[inline(always)]
    unsafe fn write_packed(own self, _ dest: *u8, room: u256) -> u256 {
        let source = self.payload_span()
        check_room(width: source.len() as u256, room)
        ptr::copy(dest, source)
        source.len() as u256
    }
}

