/// A value with a tightly packed byte encoding (Solidity
/// `abi.encodePacked` semantics).
///
/// Implementations delegate to the `Packed` append methods — no
/// encoding logic lives in the impls themselves.
pub trait EncodePacked {
    /// Exact number of bytes this value contributes.
    #[inline(always)]
    fn packed_width(self) -> u256

    /// Consume a builder, append this value, and return the builder.
    ///
    /// Passing ownership keeps generic implementations from retaining
    /// or aliasing an exclusive borrow of the builder.
    fn pack_into(own self, _ p: own Packed) -> Packed

    /// Writes the packed bytes at `dest` and returns how many were written,
    /// reverting with `Panic(0x01)` rather than write more than `room` bytes.
    ///
    /// The caller must ensure that `dest` has room for `room` bytes plus 32
    /// bytes of slack in a live allocation, because word-sized values are
    /// written with one full-word store. `room` comes from the caller's own
    /// `packed_width()` calls, which a safe implementation need not answer
    /// the same way twice, so implementations check it.
    /// The default goes through a `Packed` builder; std's implementations
    /// store their bytes directly.
    #[inline(always)]
    unsafe fn write_packed(own self, _ dest: *u8, room: u256) -> u256 {
        let packed = self.pack_into(Packed::with_capacity(bytes: 0))
        let source = packed.buffer.span()
        check_room(width: source.len() as u256, room)
        ptr::copy(dest, source)
        source.len() as u256
    }
}

/// Reverts with `Panic(0x01)` when `width` bytes do not fit in `room`.
#[inline(always)]
fn check_room(width: u256, room: u256) {
    if width > room {
        revert_error(Panic::from(PANIC_ASSERT))
    }
}

/// Writes the low `width` bytes of `value` big-endian at `dest` with a single
/// word store (clobbering the following `32 - width` bytes) and returns `width`,
/// reverting when `width` exceeds `room`.
/// The caller must ensure that `dest` has room for `room` bytes plus 32 bytes
/// of slack.
#[inline(always)]
pub(ingot) unsafe fn write_word_prefix(_ dest: *u8, _ value: u256, _ width: u256, room: u256) -> u256 {
    check_room(width, room)
    store_word(ptr: dest, value: value << ((32 - width) * 8))
    width
}

/// Pack a value (typically a tuple) into an exactly-sized fresh buffer.
///
/// The returned builder holds exactly the packed encoding; call
/// `keccak256`, `sha256`, or `as_bytes` on it, or keep appending.
#[inline(always)]
pub fn encode_packed<T: EncodePacked>(_ value: own T) -> Packed {
    let width = value.packed_width()
    var buffer = ptr::MemBuffer::with_capacity((width + 32) as usize)
    let written = unsafe { value.write_packed(buffer.ptr(), room: width) }
    unsafe { buffer.set_len(written as usize) }
    Packed { buffer }
}

/// keccak256 of the packed encoding — the dominant consumer.
#[inline(always)]
pub fn keccak_packed<T: EncodePacked>(_ value: own T) -> u256 {
    let width = value.packed_width()
    let buffer = ptr::alloc_bytes(width + 32)
    let written = unsafe { value.write_packed(buffer, room: width) }
